inline bool loadNeuralWeightsFromFile(const char* path, NeuralWeights& out) {
  if (!path || !*path) return false;
  std::FILE* f = std::fopen(path, "rb");
  if (!f) return false;
  const size_t read = std::fread(&out, sizeof(NeuralWeights), 1, f);
  std::fclose(f);
  return read == 1;
}

